-- 2. VENDORS / LABELS
INSERT INTO public.vendors (id, slug, name, letter, tagline, origin, city, gender, categories, price_range, featured, color, cover_image, product_count, coordinates, is_thrift, specialty, condition_standard, about_story, established_year, dispatch_hub, contact_phone, instagram, commission_rate)
VALUES (1, 'lesupa-atelier', 'Lesupa Atelier', 'L', 'Pretoria minimalist luxury, 280 GSM heavyweight tees & architectural embroidery', 'Arcadia / Hatfield, Pretoria', 'Pretoria', '{"UNISEX","MEN","WOMEN"}', '{"pretoria","outerwear","workwear","accessories"}', 'R 450 - R 1,400', true, '#C88A35', 'https://images.unsplash.com/photo-1509967419530-da38b4704bc6?auto=format&fit=crop&w=1600&q=85', 42, '25.7479° S, 28.2293° E', false, 'High-GSM Combed Cotton & Minimalist Boxy Cut', '', 'Founded in Hatfield, Pretoria, Lesupa Atelier bridges Scandinavian architectural restraint with unapologetic South African street presence. Every garment is crafted from custom-milled 280 GSM ring-spun cotton with dropped shoulder seams and tone-on-tone embroidery, built for the discerning capital city tastemaker.', '2021', 'Pretoria Hatfield Hub (Bob Go Couriers)', '+27 12 345 6789', '', 0.13)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, tagline = EXCLUDED.tagline, cover_image = EXCLUDED.cover_image;
INSERT INTO public.vendors (id, slug, name, letter, tagline, origin, city, gender, categories, price_range, featured, color, cover_image, product_count, coordinates, is_thrift, specialty, condition_standard, about_story, established_year, dispatch_hub, contact_phone, instagram, commission_rate)
VALUES (2, 'mokasi', 'Mokasi Streetwear', 'M', 'Pretoria urban silhouettes, oversized double-knit tracksuits & bold streetwear prints', 'Mamelodi & Soshanguve, Pretoria', 'Pretoria', '{"UNISEX","MEN","WOMEN"}', '{"pretoria","outerwear"}', 'R 650 - R 1,650', true, '#111827', 'https://images.unsplash.com/photo-1556905055-8f358a7a47b2?auto=format&fit=crop&w=1600&q=85', 38, '25.7069° S, 28.3275° E', false, 'Oversized Streetwear Cuts & Heavy Cotton Interlock', '', 'Born from the vibrant streets of Mamelodi and Soshanguve, Mokasi represents the raw, dynamic energy of Pretoria youth culture. Known for extreme volume through the sleeves, heavyweight 420 GSM double-knit tracksuits, and deep cultural graphics, Mokasi has become a hallmark of Pretoria streetwear pride.', '2019', 'Pretoria Central Distribution (Bob Go Couriers)', '+27 12 345 6789', '', 0.13)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, tagline = EXCLUDED.tagline, cover_image = EXCLUDED.cover_image;
INSERT INTO public.vendors (id, slug, name, letter, tagline, origin, city, gender, categories, price_range, featured, color, cover_image, product_count, coordinates, is_thrift, specialty, condition_standard, about_story, established_year, dispatch_hub, contact_phone, instagram, commission_rate)
VALUES (3, 'galxboy', 'Galxboy Heritage Drop', 'G', 'Pretoria''s pioneer streetwear legacy — iconic graphic silhouettes & statement headwear', 'Menlyn / Pretoria, 012', 'Pretoria', '{"UNISEX","MEN","WOMEN"}', '{"pretoria","accessories","outerwear"}', 'R 450 - R 1,950', true, '#C88A35', 'https://images.unsplash.com/photo-1551028719-00167b16eac5?auto=format&fit=crop&w=1600&q=85', 56, '25.7825° S, 28.2755° E', false, 'Iconic SA Pop Culture & Heavy Melton Varsity Jackets', '', 'Starting as a humble T-shirt brand in Pretoria and evolving into a national cultural juggernaut, Galxboy paved the way for modern South African urban fashion. This curated heritage drop features premium varsity outerwear, heavyweight chenille patches, and archival collector items.', '2008', 'Menlyn Retail Logistics Hub', '+27 12 345 6789', '', 0.13)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, tagline = EXCLUDED.tagline, cover_image = EXCLUDED.cover_image;
INSERT INTO public.vendors (id, slug, name, letter, tagline, origin, city, gender, categories, price_range, featured, color, cover_image, product_count, coordinates, is_thrift, specialty, condition_standard, about_story, established_year, dispatch_hub, contact_phone, instagram, commission_rate)
VALUES (4, 'soweto-threads', 'Soweto Threads', 'S', 'Heritage raw selvage denim, chainstitched tailoring & formal pleats', 'Orlando West, Soweto', 'Soweto', '{"MEN","WOMEN","UNISEX"}', '{"workwear","outerwear"}', 'R 780 - R 1,800', true, '#1E3A8A', 'https://images.unsplash.com/photo-1576995853123-5a10305d93c0?auto=format&fit=crop&w=1600&q=85', 48, '26.2415° S, 27.9157° E', false, '14oz Raw Red-Line Selvage Denim & Chainstitching', '', 'Handcrafted in an Orlando West studio just blocks from Vilakazi Street, Soweto Threads pays homage to historic township tailoring and the refined Swenka aesthetic. Utilizing Japanese shuttle-loom shuttle selvage denim, every jacket and trouser is built to develop a singular patina personal to the wearer.', '2018', 'Soweto Diepkloof Spaza Station (Bob Go)', '+27 12 345 6789', '', 0.13)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, tagline = EXCLUDED.tagline, cover_image = EXCLUDED.cover_image;
INSERT INTO public.vendors (id, slug, name, letter, tagline, origin, city, gender, categories, price_range, featured, color, cover_image, product_count, coordinates, is_thrift, specialty, condition_standard, about_story, established_year, dispatch_hub, contact_phone, instagram, commission_rate)
VALUES (5, 'braam-district', 'Braam District', 'B', '480 GSM heavy fleece & commuter technical silhouettes', 'Braamfontein, Johannesburg', 'Johannesburg', '{"UNISEX","MEN","WOMEN"}', '{"outerwear","accessories"}', 'R 520 - R 1,200', true, '#111827', 'https://images.unsplash.com/photo-1509967419530-da38b4704bc6?auto=format&fit=crop&w=1600&q=85', 64, '26.1929° S, 28.0345° E', false, 'Heavy Cotton & Tactile Cargo Details', '', 'Braam District is the uniform of Johannesburg''s creative core. Designed steps from Park Station and the Nelson Mandela Bridge, their gear focuses on ultra-heavyweight 480 GSM French terry fleece, waterproof Cordura accessories, and thermal layering tailored for Highveld winters.', '2020', 'Braamfontein Juta Smart Locker', '+27 12 345 6789', '', 0.13)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, tagline = EXCLUDED.tagline, cover_image = EXCLUDED.cover_image;
INSERT INTO public.vendors (id, slug, name, letter, tagline, origin, city, gender, categories, price_range, featured, color, cover_image, product_count, coordinates, is_thrift, specialty, condition_standard, about_story, established_year, dispatch_hub, contact_phone, instagram, commission_rate)
VALUES (6, 'gusheshe-classics', 'Gusheshe Classics', 'G', 'Vulcanized footwear inspired by South African motorsport & spinning heritage', 'Pinetown, KwaZulu-Natal', 'Durban', '{"UNISEX","MEN"}', '{"kicks"}', 'R 1,450 - R 2,200', true, '#C88A35', 'https://images.unsplash.com/photo-1549298916-b41d501d3772?auto=format&fit=crop&w=1600&q=85', 32, '29.8167° S, 30.8500° E', false, 'Vulcanized Waffle Sole & Suede Motorsport Overlays', '', 'Engineered in Pinetown, KwaZulu-Natal, Gusheshe Classics translates South Africa''s legendary BMW E30 325i spinning and motorsport culture into vulcanized sneaker architecture. Featuring tire-tread gum rubber outsoles, reinforced double toe-caps, and memory foam insoles built for longevity.', '2022', 'Durban Central Pargo Station', '+27 12 345 6789', '', 0.13)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, tagline = EXCLUDED.tagline, cover_image = EXCLUDED.cover_image;
INSERT INTO public.vendors (id, slug, name, letter, tagline, origin, city, gender, categories, price_range, featured, color, cover_image, product_count, coordinates, is_thrift, specialty, condition_standard, about_story, established_year, dispatch_hub, contact_phone, instagram, commission_rate)
VALUES (7, 'dunusa-archive', 'Dunusa Archive Co.', 'D', 'Curated 1-of-1 90s sportswear, crinkle nylon windbreakers & motorsport track tops', 'Small Street CBD, Johannesburg', 'Johannesburg', '{"UNISEX","MEN","WOMEN"}', '{"thrift","outerwear"}', 'R 380 - R 890', true, '#059669', 'https://images.unsplash.com/photo-1548883354-7622d03aca27?auto=format&fit=crop&w=1600&q=85', 26, '26.2023° S, 28.0471° E', true, '90s Sportswear & Technical Windbreakers', 'Grade A+ Flawless Mint (Steam Cleaned)', 'Scouting daily across the labyrinthine wholesale bales of Small Street CBD, Dunusa Archive Co. hand-picks the rarest 1990s Italian and American technical windbreakers, racing jackets, and motorsport track tops. Every piece is triple steam-cleaned, measured to the centimeter, and guaranteed 1-of-1.', '2017', 'Johannesburg CBD Vault', '+27 12 345 6789', '', 0.13)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, tagline = EXCLUDED.tagline, cover_image = EXCLUDED.cover_image;
INSERT INTO public.vendors (id, slug, name, letter, tagline, origin, city, gender, categories, price_range, featured, color, cover_image, product_count, coordinates, is_thrift, specialty, condition_standard, about_story, established_year, dispatch_hub, contact_phone, instagram, commission_rate)
VALUES (8, 'kasi-vintage-vault', 'Kasi Vintage Vault', 'K', 'Sophiatown heavy leather flight jackets, vintage knit polos & pleated trousers', 'Diepkloof Zone 2, Soweto', 'Soweto', '{"MEN","UNISEX"}', '{"thrift","workwear","outerwear","accessories"}', 'R 380 - R 1,450', true, '#B45309', 'https://images.unsplash.com/photo-1520975954732-35dd22299614?auto=format&fit=crop&w=1600&q=85', 19, '26.2482° S, 27.9401° E', true, 'Heavy Leathers & 70s Sophiatown Knits', 'Grade A Mint (Conditioned Leather)', 'Preserving the legendary style of Sophiatown jazz pioneers and Soweto sartorialists, Kasi Vintage Vault unearths archival heavyweight shearling leather jackets, fine wool knits, and hand-tooled brass-buckle belts. Deeply conditioned with organic oils to last decades.', '2016', 'Diepkloof Zone 4 Spaza Hub', '+27 12 345 6789', '', 0.13)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, tagline = EXCLUDED.tagline, cover_image = EXCLUDED.cover_image;
