VALUES (9, 'bree-st-reworks', 'Bree St. Reworks', 'B', '1-of-1 upcycled workwear vests, patched raw denim & commuter canvas gear', 'Bree Taxi Interchange, Johannesburg', 'Johannesburg', '{"UNISEX","MEN","WOMEN"}', '{"thrift","workwear"}', 'R 480 - R 920', true, '#4B5563', 'https://images.unsplash.com/photo-1516257984-b1b4d707412e?auto=format&fit=crop&w=1600&q=85', 22, '26.1989° S, 28.0380° E', true, 'Reworked Duck Canvas & Patchwork', 'Upcycled Heritage Grade (Triple Reinforced)', 'Situated at the pulsing heart of Johannesburg transit, Bree St. Reworks deconstructs decommissioned transit overalls, heavy duck canvas jackets, and mining uniforms into functional modern streetwear vests and carryalls with brass D-rings and industrial stitching.', '2021', 'Bree Taxi Interchange Station', '+27 12 345 6789', '', 0.13)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, tagline = EXCLUDED.tagline, cover_image = EXCLUDED.cover_image;
