INSERT INTO public.vendors (id, slug, name, letter, tagline, origin, city, gender, categories, price_range, featured, color, cover_image, product_count, coordinates, is_thrift, specialty, condition_standard, about_story, established_year, dispatch_hub, contact_phone, instagram, commission_rate)
VALUES (11, 'urban-soul', 'Urban Soul', 'U', 'Pretoria streetwear crafted from garage cuts to capital culture', 'Pretoria, South Africa', 'Pretoria', '{"UNISEX","MEN","WOMEN"}', '{"outerwear","workwear","accessories","pretoria"}', 'R 320 - R 849', true, '#d6a34c', 'https://images.unsplash.com/photo-1509967419530-da38b4704bc6?auto=format&fit=crop&w=1600&q=85', 36, '25.7461° S, 28.1881° E', false, '420 GSM Boxy Hoodies & Heavyweight Cargo Twill', '', 'Thabo started Urban Soul in his mother''s garage, cutting his first run of ten hoodies for friends at TUT. He wanted streetwear that felt like Pretoria, not a copy of something overseas.', '2023', 'Pretoria Central Depot (Bob Go Couriers)', '+27 71 832 9481', '@urbansoul_pta', 0.08)
